cypress_script:
describe('Dynamic Loading', () => {
  it('should load content asynchronously', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('button').contains('Start').click();
    cy.get('#finish').should('be.visible');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  it('should not show content immediately after clicking start', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('button').contains('Start').click();
    cy.get('#finish').should('not.exist');
  });
});

playwright_script:
test.describe('Dynamic Loading', () => {
  test('should load content asynchronously', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await page.click('button:text("Start")');
    await page.waitForSelector('#finish');
    const url = page.url();
    expect(url).toBe('https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  test('should not show content immediately after clicking start', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await page.click('button:text("Start")');
    const finishVisible = await page.isVisible('#finish');
    expect(finishVisible).toBeFalsy();
  });
});
